void tampilkanPemenang(int player){
    if(player == 1){
        for(int i = 0; i < 6; i++){
            tampilkanCepat(player1Menang[i]);
            std::this_thread::sleep_for(std::chrono::seconds(1));
        }
    }
    else{
        for(int i = 0; i < 6; i++){
            tampilkanCepat(player2Menang[i]);
            std::this_thread::sleep_for(std::chrono::seconds(1));
        }
    }
    std::this_thread::sleep_for(std::chrono::seconds(5));
    Erase_Screen();
}